class Line:
    description: str
    unit_price: Decimal
    quantity: int = 1
    discount_pct: Decimal = Decimal("0")  # percentage points: 10 means 10%

    @property
    def total(self):
        gross = self.unit_price * self.quantity
        if self.discount_pct == 0:
